/**
 * The one-time question after a first Sign in with Apple that hid the
 * address: "Already have a Lexpad account?" (features/onboarding/ExistingAccount).
 *
 * A relay address matches nothing, so such a sign-in always makes a new
 * account, even for somebody who already has one. The question is asked
 * once, before onboarding, for that account only. It lives in localStorage
 * because it must survive the app being closed on the question; it is a
 * marker, not data, and losing it only means the question is not asked
 * (Settings → Account → Sign-in methods still joins the accounts).
 */
const KEY = 'lexpad.linkOffer';

/** Asks the question the next time this account reaches onboarding. */
export function offerLink(userId: string): void {
  try {
    localStorage.setItem(KEY, userId);
  } catch {
    // Storage blocked: the question is skipped; Settings still offers it.
  }
}

/** Whether the question is waiting for this account. */
export function linkOfferPending(userId: string | undefined): boolean {
  if (userId === undefined) return false;
  try {
    return localStorage.getItem(KEY) === userId;
  } catch {
    return false;
  }
}

/** The question was answered, either way. */
export function dismissLinkOffer(): void {
  try {
    localStorage.removeItem(KEY);
  } catch {
    // Nothing to forget.
  }
}
