/**
 * The lifecycle note an app session was opened through (24 Oct 2026,
 * marketing/emails/2026-10-24-l1-l2-rewrite.md). Every link in a lifecycle
 * e-mail or pop-up carries `ref=em-<template>-<variant>` or
 * `pn-<message>-<variant>`. The app keeps that ref and sends it once, with
 * the device registration (`registerDevice`), so the operator's panel can
 * count how many notes were followed into the app. The links stay direct
 * (no click-counting redirect), which is what lets a phone open its app for
 * an app link.
 *
 * It is a word, never an address or a click id, and it goes only to our own
 * API. It lives in sessionStorage, like the OAuth state: one app session's
 * worth, so a reload does not send it again; nothing about the learner is
 * kept there, and with storage refused it is held in memory instead.
 */
const KEY = 'lexpad.arrival';

/** The shape of a note's ref; anything else (a sign-up source, an invitation) is not one. */
const ARRIVAL = /^(em|pn)-[a-z0-9][a-z0-9-]{0,60}$/;

interface Held {
  ref: string;
  sent: boolean;
}

let memory: Held | undefined;

function read(): Held | undefined {
  try {
    const raw = sessionStorage.getItem(KEY);
    if (raw !== null) {
      const value = JSON.parse(raw) as Partial<Held>;
      if (typeof value.ref === 'string' && ARRIVAL.test(value.ref))
        return { ref: value.ref, sent: value.sent === true };
    }
  } catch {
    // Storage refused or garbled: the copy in memory is all there is.
  }
  return memory;
}

function write(held: Held): void {
  memory = held;
  try {
    sessionStorage.setItem(KEY, JSON.stringify(held));
  } catch {
    // Storage refused: memory keeps it for this page.
  }
}

/** The query string of an address the app is at: `?…` itself, or the part after `?` in a `#/path?…` route. */
export function searchOf(searchOrHash: string): string {
  const at = searchOrHash.indexOf('?');
  return at === -1 ? '' : searchOrHash.slice(at);
}

/** A note's ref in a query string, or undefined. */
export function arrivalRef(search: string): string | undefined {
  let ref: string | null;
  try {
    ref = new URLSearchParams(searchOf(search)).get('ref');
  } catch {
    return undefined;
  }
  const value = ref?.trim().toLowerCase();
  return value !== undefined && ARRIVAL.test(value) ? value : undefined;
}

/**
 * Notes the note an address came from. True when it is one this session has
 * not held yet, so a caller that is already signed in sends it now; the same
 * ref twice (a reload, the same link tapped again) is never sent twice.
 */
export function noteArrival(search: string): boolean {
  const ref = arrivalRef(search);
  if (ref === undefined || read()?.ref === ref) return false;
  write({ ref, sent: false });
  return true;
}

/** The ref still to send with the next registration, if any. */
export function pendingArrival(): string | undefined {
  const held = read();
  return held !== undefined && !held.sent ? held.ref : undefined;
}

/** Marks a ref as delivered, so no later registration repeats it. */
export function arrivalSent(ref: string): void {
  if (read()?.ref === ref) write({ ref, sent: true });
}

/** Forgets everything; for tests. */
export function __resetArrivalForTests(): void {
  memory = undefined;
  try {
    sessionStorage.removeItem(KEY);
  } catch {
    // Nothing to forget.
  }
}
