import { t } from '@/i18n/index.js';

/**
 * Apple's private relay domain: the addresses Sign in with Apple hands out
 * when somebody chooses "Hide My Email". It is Apple's, the same for every
 * app, so it is a constant. The server says so too (`emailHidden`); this is
 * for an account stored by an older build, before it reads the profile again.
 */
export const PRIVATE_RELAY_DOMAIN = 'privaterelay.appleid.com';

/** Whether an address is an Apple private relay address. */
export function isPrivateRelay(email: string): boolean {
  const at = email.lastIndexOf('@');
  return at >= 0 && email.slice(at + 1).toLowerCase() === PRIVATE_RELAY_DOMAIN;
}

/**
 * The account's address as the app shows it. A relay address is a
 * forwarding alias the learner never typed and would not recognise, so it is
 * never shown as if it were theirs: the screen says Apple hides it.
 */
export function accountAddress(user: { email: string; emailHidden?: boolean }): string {
  return user.emailHidden === true || isPrivateRelay(user.email) ? t('account.emailHidden') : user.email;
}
